<div class="seom-panel"><div class="seom-actions"><h3>Indexing History</h3><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="seom_indexnow_clear_logs"><?php wp_nonce_field('seom_indexnow_clear_logs'); ?><button class="button">Clear IndexNow/Bing History</button></form></div><div style="overflow:auto"><table class="widefat striped"><thead><tr><th>Provider</th><th>URL</th><th>Action</th><th>Status</th><th>Code</th><th>Message</th><th>Time</th></tr></thead><tbody><?php if(!$logs): ?><tr><td colspan="7">No Search Engine Indexing requests yet.</td></tr><?php else: foreach($logs as $r): ?><tr><td><?php echo esc_html($r['provider']??'indexnow'); ?></td><td style="max-width:320px;overflow-wrap:anywhere"><?php echo esc_html($r['url']); ?></td><td><?php echo esc_html(strtoupper($r['action'])); ?></td><td><span class="seom-badge <?php echo $r['status']==='success'?'ok':($r['status']==='queued'?'warn':'bad'); ?>"><?php echo esc_html($r['status']); ?></span></td><td><?php echo (int)$r['response_code']; ?></td><td><?php echo esc_html($r['message']); ?></td><td><?php echo esc_html($r['created_at']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
